import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ref, onValue, update } from 'firebase/database';
import { db } from '../firebase';

function SeriesDetail() {
  const { id } = useParams();
  const [series, setSeries] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedSeason, setSelectedSeason] = useState(1);
  const [watchedEpisodes, setWatchedEpisodes] = useState({
    mucahit: {},
    beyza: {}
  });

  useEffect(() => {
    const seriesRef = ref(db, `series/${id}`);
    const unsubscribe = onValue(seriesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setSeries(data);
        setWatchedEpisodes(data.watchedEpisodes || { mucahit: {}, beyza: {} });
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  const toggleEpisodeWatched = async (season, episode, user) => {
    const episodeKey = `${season}-${episode}`;
    const newWatchedEpisodes = {
      ...watchedEpisodes,
      [user]: {
        ...watchedEpisodes[user],
        [episodeKey]: !watchedEpisodes[user][episodeKey]
      }
    };

    try {
      const seriesRef = ref(db, `series/${id}`);
      await update(seriesRef, {
        watchedEpisodes: newWatchedEpisodes
      });
      setWatchedEpisodes(newWatchedEpisodes);
    } catch (error) {
      console.error('Error updating episode status: ', error);
      alert('Bölüm durumu güncellenirken bir hata oluştu.');
    }
  };

  const toggleSeasonWatched = async (season, user) => {
    const episodes = Array.from({ length: series.episodesPerSeason }, (_, i) => i + 1);
    const newWatchedEpisodes = {
      ...watchedEpisodes,
      [user]: {
        ...watchedEpisodes[user]
      }
    };

    const allWatched = episodes.every(episode => 
      watchedEpisodes[user][`${season}-${episode}`]
    );

    episodes.forEach(episode => {
      newWatchedEpisodes[user][`${season}-${episode}`] = !allWatched;
    });

    try {
      const seriesRef = ref(db, `series/${id}`);
      await update(seriesRef, {
        watchedEpisodes: newWatchedEpisodes
      });
      setWatchedEpisodes(newWatchedEpisodes);
    } catch (error) {
      console.error('Error updating season status: ', error);
      alert('Sezon durumu güncellenirken bir hata oluştu.');
    }
  };

  if (loading) {
    return (
      <div className="text-center">
        <p className="text-xl">Yükleniyor...</p>
      </div>
    );
  }

  if (!series) {
    return (
      <div className="text-center">
        <p className="text-xl">Dizi bulunamadı.</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-md p-8">
      <div className="flex justify-between items-start mb-6">
        <div>
          <h2 className="text-2xl font-bold text-purple-600">{series.title}</h2>
          <p className="text-gray-600">
            Sezon {series.currentSeason} Bölüm {series.currentEpisode}
          </p>
        </div>
        <Link
          to={`/series/${id}/edit`}
          className="bg-purple-600 text-white py-2 px-4 rounded-lg hover:bg-purple-700 transition duration-200"
        >
          Düzenle
        </Link>
      </div>

      {series.coverImage && (
        <div className="mb-6">
          <img
            src={series.coverImage}
            alt={series.title}
            className="w-full h-64 object-cover rounded-lg"
          />
        </div>
      )}
      
      <div className="mb-8">
        <div className="grid grid-cols-2 gap-4 text-gray-600">
          <div>
            <p className="font-semibold">Toplam Sezon:</p>
            <p>{series.totalSeasons}</p>
          </div>
          <div>
            <p className="font-semibold">Sezon Başına Bölüm:</p>
            <p>{series.episodesPerSeason}</p>
          </div>
          <div>
            <p className="font-semibold">Mevcut Sezon:</p>
            <p>{series.currentSeason}</p>
          </div>
          <div>
            <p className="font-semibold">Mevcut Bölüm:</p>
            <p>{series.currentEpisode}</p>
          </div>
          <div>
            <p className="font-semibold">İzleme Durumu:</p>
            <p>{series.watchingTogether ? 'Birlikte İzliyoruz' : 'Ayrı İzliyoruz'}</p>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <h3 className="text-xl font-bold text-purple-600">Bölümler</h3>
        {Array.from({ length: series.currentSeason }, (_, seasonIndex) => {
          const season = seasonIndex + 1;
          const seasonEpisodes = Array.from(
            { length: season === series.currentSeason ? series.currentEpisode : series.episodesPerSeason },
            (_, i) => `${season}-${i + 1}`
          );
          const isSeasonWatched = seasonEpisodes.every(ep => watchedEpisodes.includes(ep));
          
          return (
            <div key={season} className="border rounded-lg p-4">
              <div className="flex justify-between items-center mb-3">
                <h4 className="text-lg font-semibold">Sezon {season}</h4>
                <div className="space-x-2">
                  <button
                    onClick={() => toggleSeasonWatched(season, true)}
                    className="bg-green-500 text-white py-1 px-3 rounded hover:bg-green-600 transition duration-200"
                  >
                    Tümünü İzledim
                  </button>
                  <button
                    onClick={() => toggleSeasonWatched(season, false)}
                    className="bg-red-500 text-white py-1 px-3 rounded hover:bg-red-600 transition duration-200"
                  >
                    Tümünü İzlemedim
                  </button>
                </div>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2">
                {Array.from(
                  { length: season === series.currentSeason ? series.currentEpisode : series.episodesPerSeason },
                  (_, episodeIndex) => {
                    const episodeKey = `${season}-${episodeIndex + 1}`;
                    const isWatched = watchedEpisodes.includes(episodeKey);
                    
                    return (
                      <button
                        key={episodeIndex + 1}
                        onClick={() => toggleEpisodeWatched(season, episodeIndex + 1)}
                        className={`p-2 rounded-lg text-center ${
                          isWatched
                            ? 'bg-green-500 text-white'
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                      >
                        Bölüm {episodeIndex + 1}
                      </button>
                    );
                  }
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default SeriesDetail;
